const zipPattern = /^[0-9]{5}(-[0-9]{4})?$/;

const cases = [
  { input: "02134", expected: true },       // 5-digit, leading zero
  { input: "12345-6789", expected: true },  // ZIP+4
  { input: "12345-67890", expected: false }, // too many digits after hyphen
